R=Path(__file__).resolve().parent;B='https://perhardt7686.github.io/cowboys-web-toolbox/'
def setup(d):
 ds=d['discovery'];by={s['id']:s for s in d['sites']};fields={'pricing':('Cost',[('free','Free core use'),('freemium','Limited free / paid extras'),('paid','Paid'),('unknown','Cost unknown')]),'signup':('Account',[('no','No account required'),('optional','Optional / some features'),('yes','Account required'),('unknown','Signup unknown')]),'platform':('Device',[('browser','Web browser'),('windows','Windows'),('mac','macOS'),('linux','Linux'),('ios','iPhone / iPad'),('android','Android'),('unknown','Unknown')]),'checked':('Checks',[('recent','Reviewed within 30 days'),('tested','Task tested'),('unverified','Availability unverified')]),'offline':('Offline support',[('yes','Documented offline use'),('no','Internet required'),('unknown','Unknown')]),'processing':('File processing',[('local','Local for documented task'),('cloud','Sent to provider'),('mixed','Depends on feature'),('unknown','Unknown')]),'commercial':('Commercial use',[('allowed','Documented permission'),('restricted','Restrictions / item licenses'),('unknown','Unknown')]),'kind':('Type',[('tool','Interactive tool'),('reference','Reference / lessons'),('directory','Directory / search'),('download','Installed software'),('experience','Game / experience'),('unknown','Unknown')]),'region':('Region',[('global','International resource'),('us','US focus / eligibility'),('unknown','Region unknown')]),'language':('Language',[('en','English documented'),('es','Spanish documented'),('multilingual','Multiple languages documented'),('unknown','Unknown')]),'audience':('Starting points',[('beginner','Beginner starting points'),('family','Family starting points'),('classroom','Classroom starting points'),('unknown','Not assessed')])}
 def select(k):
  label,vs=fields[k];return '<label>'+label+'<select id="filter-'+k+'"><option value="all">Any '+label.lower()+'</option>'+''.join('<option value="'+v+'">'+e(t)+'</option>' for v,t in vs)+'</select></label>'
 basic=['pricing','signup','platform','checked'];filters='<div id="discovery-filters" class="discovery-filters"><div class="filter-row">'+''.join(select(k) for k in basic)+'</div><details class="more-filters"><summary>More filters · privacy, license, region & topic</summary><div class="filter-row"><label id="topic-filter-label">Topic<select id="topic-filter"><option value="All">Every topic</option></select></label><label>Finds from<select id="origin-filter"><option value="all">Everywhere</option><option value="video">Source videos</option><option value="web">Web research</option><option value="community">The community</option></select></label>'+''.join(select(k) for k in fields if k not in basic)+'</div><p class="filter-note">Unknown means unverified. Free describes core access; purchases, materials, licenses or extra features may cost money. Family and classroom labels are starting points; adults should review current third-party content.</p></details></div>'
 packs='<section class="container starter-section" id="starter-packs"><div class="section-line"><div><p class="eyebrow">A little direction</p><h2>Start with what you want to do.</h2></div><a href="help.html">How to use this Toolbox ↗</a></div><div class="pack-grid">'+''.join('<a class="pack-link" href="pack-'+p['id']+'.html" data-pack="'+p['id']+'"><strong>'+e(p['title'])+' ↗</strong><span>'+e(p['outcome'])+'</span></a>' for p in ds['packs'])+'</div></section>'
 paths=['index.html','community.html']
 def page(name,title,description,body):
  paths.append(name);canonical=B+name
  content='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+' — Cowboy’s Toolbox</title><meta name="description" content="'+e(description,quote=True)+'"><link rel="canonical" href="'+canonical+'"><meta property="og:title" content="'+e(title,quote=True)+'"><meta property="og:description" content="'+e(description,quote=True)+'"><meta property="og:image" content="'+B+'share-card.png"><meta property="og:url" content="'+canonical+'"><link rel="icon" href="favicon.svg"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="discovery.css"><style>.guide{max-width:850px;padding-block:40px 65px}.guide h1{font-size:clamp(38px,6vw,58px);letter-spacing:-1.5px;line-height:1.1}.guide h2{font:400 29px Georgia,serif;margin-top:34px}.guide p,.guide li,.guide dd{font-size:16px;line-height:1.8}.guide dt{margin-top:15px}.guide dd{margin-left:0}.guide a{overflow-wrap:anywhere}.guide .plain-button{display:inline-flex;text-decoration:none;align-items:center;margin:5px}.guide details{border-bottom:1px solid #cbd4bd;padding:15px 0}.guide summary{min-height:44px;font-size:17px}.guide-step{padding:18px 0;border-bottom:1px solid #cbd4bd}</style></head><body><a class="skip" href="#main">Skip to content</a><header class="masthead"><div class="container header-inner"><a class="brand" href="./">✳ COWBOY’S TOOLBOX</a><nav aria-label="Main navigation"><a href="./#explore">Explore tools</a><a class="nav-board" href="community.html">MESSAGE BOARDS! ↗</a></nav></div></header><main id="main" class="container guide"><p class="eyebrow">Useful tools for everyone</p><h1>'+e(title)+'</h1><p>'+e(description)+'</p>'+body+'</main><footer class="container footer"><a href="./">Back to the Toolbox</a><nav aria-label="Trust and help"><a href="privacy.html">Privacy</a><a href="editorial.html">How we choose</a><a href="help.html">Help</a><a href="community.html?compose=site-report">Report / contact Cowboy</a></nav></footer></body></html>'
  (R/'docs'/name).write_text(content)
 for id,steps in ds['guides'].items():
  s=by[id];a=s['access'];body='<p><a class="board-link" href="'+e(s['url'],quote=True)+'" target="_blank" rel="noopener noreferrer">Visit '+e(s['name'])+' ↗</a></p><h2>Is this a fit?</h2><dl>'
  for k,v in [('Best for',s['bestFor']),('Access',s['accessLabel']),('Signup',a['signup']),('Devices',', '.join(a['platform'])),('Offline',a['offline']),('Processing',a['processing']),('Commercial use',a['commercial']),('Region',a['region'])]:body+='<dt><strong>'+e(k)+'</strong></dt><dd>'+e(v)+'</dd>'
  body+='</dl><p class="private-hint">Unknown means unverified. '+e(s.get('privacyNote','Check current provider terms before entering personal information.'))+'</p><p>'+e(s.get('licenseNote',''))+'</p><h2>Try one small task</h2><ol>'+''.join('<li>'+e(t)+'</li>' for t in steps)+'</ol><h2>What was checked</h2>'
  test=s.get('workflowTest');body+='<p><strong>'+('Task tested' if test and test.get('passed') else 'Provider page checked · workflow untested')+'</strong> · '+e(test['date'] if test else s.get('accessReviewedAt',s['destinationCheck'].get('checkedDate','Unknown')))+'</p><p>'+e(s['destinationCheck']['notes'])+'</p>'
  if test:body+='<p>'+e(test['task'])+' — '+e(test['scope'])+'</p>'
  body+='<p>Suggested steps are a starting point, not a promise that every device, plan or feature has been tested.</p><h2>Sources and alternatives</h2><ul>'+''.join('<li><a href="'+e(u,quote=True)+'" target="_blank" rel="noopener noreferrer">Provider source '+str(i+1)+'</a></li>' for i,u in enumerate(s.get('evidenceUrls',[s['url']])))+'</ul>'
  for p in ds['comparisons']:
   if id in p['ids']:body+='<p>Compare: '+', '.join('<a href="./?find='+e(by[x]['name'],quote=True)+'#explore">'+e(by[x]['name'])+'</a>' for x in p['ids'] if x!=id)+'</p>'
  body+='<p><a href="community.html?site='+id+'&amp;compose=review">Share a completed task</a> · <a href="community.html?site='+id+'&amp;compose=site-report">Report a change</a></p>';page('guide-'+id+'.html',s['name']+' guide',s['description'],body)
 for p in ds['packs']:
  body='<p><strong>Your outcome:</strong> '+e(p['outcome'])+'</p>'
  for i,id in enumerate(p['ids']):
   s=by[id];body+='<section class="guide-step"><h2>'+str(i+1)+'. '+e(s['name'])+'</h2><p>'+e(p['steps'][i])+'</p><p>'+e(s['description'])+'</p><p><strong>Access:</strong> '+e(s['accessLabel'])+'</p><p>'+e(s.get('privacyNote',''))+'</p><a class="plain-button" href="'+e(s['url'],quote=True)+'" target="_blank" rel="noopener noreferrer">Visit tool ↗</a>'
   if id in ds['guides']:body+='<a class="plain-button" href="guide-'+id+'.html">Read the guide ↗</a>'
   body+='</section>'
  body+='<p>These are suggested steps, not a claim that the entire pack has been tested. Verify current access and requirements.</p><a class="plain-button" href="./?pack='+p['id']+'#explore">Browse this pack</a>';page('pack-'+p['id']+'.html',p['title'],p['outcome'],body)
 page('privacy.html','Your privacy and choices','What stays in your browser, and what reaches another service.','''<h2>Private collections</h2><p>Favorites, folders and notes stay in this browser. Clearing browser data can remove them. A private JSON backup contains notes and folder names; keep it private. Import reads it locally. Sharing requires review and exposes up to 50 selected tool IDs in a link fragment. Notes and folder names are excluded. Ordinary search links include search text and filters; review them before sending.</p><h2>Clicks and optional measurements</h2><p>Destination clicks are aggregate link opens, not unique people. Events contain a catalog ID and a random event ID, with a browser cooldown and bounded server limits. Historical totals can include controlled verification events. Test/offline mode sends no events.</p><p>Additional discovery measurements are off by default. If enabled, they contain fixed buckets only: results or zero results, a broad time-to-open interval, and yes/no task feedback. Raw queries, notes, folder names, account IDs and persistent visitor IDs are excluded from these events. Aggregate totals are owner-only. Random measurement IDs expire after 24 hours; aggregate retention is 90 days. Network providers may retain routine logs.</p><h2>Third-party tools</h2><p>External tools have their own terms. Local-processing labels apply only to documented core tasks. Cloud tools receive files. Mixed or unknown processing requires checking the feature. Public security scanners can share submissions; never submit confidential material.</p><h2>The Commons</h2><p>Accounts require email verification and owner approval before posting. Published posts and shared profiles are public. Reports and account settings have separate permissions. Edward is an automated moderator with bounded catalog-based replies, without access to private ChatGPT chats or inboxes. Request account deletion through My account; a request is not completed deletion.</p><p><a class="plain-button" href="community.html?privacy=1">Board privacy controls</a><a class="plain-button" href="community.html?auth=login">Manage an account</a></p>''')
 page('editorial.html','How we choose and check','Practical tools, original sources and honest limits.','''<h2>Inclusion and sources</h2><p>A listing needs an identifiable destination, a useful purpose and source evidence. We prefer official provider documentation. Video discoveries retain attribution. Community additions retain their owner-reviewed discussion source. Inclusion is not a security certification.</p><h2>Different checks mean different things</h2><ul><li><strong>Provider page checked:</strong> source content was reviewed; account, export and billing workflows can remain untested.</li><li><strong>Task tested:</strong> one recorded harmless sample has a date and scope.</li><li><strong>Availability unverified:</strong> another check is needed. A blocked retrieval or 403 does not establish closure.</li></ul><h2>Rankings and limits</h2><p>Most clicked remains the default and measures link opens. Editor’s picks are separate starting points. New sorts by catalog addition date, not product release. Free describes core access; optional features, purchases and licenses may cost money. Unknown fields stay unknown. Commercial rights depend on the exact plan and asset.</p><h2>Maintenance and commercial relationships</h2><p>Reports enter owner review. The weekly bounded link check produces an Actions report; a page response is not a completed workflow or pricing review. If affiliate or sponsored links are introduced, they must be labeled and editorial choices remain independent. This update adds no affiliate links, subscription or paid service.</p><a href="review.html">See the review queue</a>''')
 page('help.html','Find a tool and finish a task','Search, compare and save with a few useful controls.','''<h2>Search the task</h2><p>Try join PDF, background remover, résumé or repair. Search covers the entire catalog; 24 results render at a time. Aliases and light spelling tolerance help ordinary task phrases. Exact and task matches rank before incidental words.</p><h2>Filters and collections</h2><p>Narrow by purpose, cost, signup or device. More filters include processing, commercial use and region. Unknown is an honest answer. Remove one active filter or clear all. Search and public filters survive refresh and can be shared. Private folder names are kept out of public links. Compare up to three tools.</p><h2>Keyboard and readability</h2><p>Press / to focus search, use Tab to move and arrow keys to switch tabs. Escape closes a dialog. Visible outlines and result announcements support keyboard users. Compact view omits illustrations. The motion toggle and reduced-motion preference are retained. Actual iPhone Safari, Android Chrome and screen-reader testing with real users remain separate from browser and automated checks.</p><h2>Language and offline use</h2><p>The selector translates main navigation and search prompts into Spanish. Listing descriptions, filters and external websites mostly retain their original language; this is not a complete translation. Family/classroom labels are starting points, not content guarantees. The HTML download contains catalog controls and data. External tools, boards and guide links still require internet or the matching site files.</p><a class="plain-button" href="community.html?compose=site-report">Report an accessibility problem</a>''')
 page('test-with-us.html','Help test the Toolbox','Try a small real task, then tell Cowboy what happened.','''<ol><li>Choose a harmless task: merge PDFs, find a résumé example, sketch a diagram, find a model’s manual or compare image tools.</li><li>Start from search or a starter pack. Note confusing wording, changed prices and account requirements.</li><li>Inspect the final result. Opening a tool is different from finishing.</li><li>Share the task, device/browser, result and obstacle. Use fictional or public sample content.</li></ol><p>Beginners, teachers, tradespeople and people using accessibility features are welcome. Participation is voluntary. No payment, prize or reward is promised. Board posting requires verification and owner approval. Do not post passwords, private files or other people’s personal information.</p><a class="board-link" href="community.html?compose=project">Share a completed task ↗</a>''')
 queue=[]
 for s in d['sites']:
  if s['destinationCheck']['status']=='availability_unverified':queue.append('<section class="guide-step"><h2>'+e(s['name'])+'</h2><p>Availability needs review. A blocked or incomplete retrieval is not a closure claim.</p><a href="./?find='+e(s['name'],quote=True)+'#explore">Inspect listing ↗</a></section>')
 page('review.html','A little maintenance goes a long way','The published availability review queue.','<p>The bounded weekly checker examines up to 32 public pages and saves a dated report in Actions. It does not change prices, hide listings or declare a provider closed. Public reports and changed limits need owner review. Volatile paid/freemium tools are due for review after 30 days; stable references after 90 days.</p><p><a class="plain-button" href="https://github.com/perhardt7686/cowboys-web-toolbox/actions">Scheduled reports ↗</a><a class="plain-button" href="community.html?compose=site-report">Report a change</a></p><p>'+str(len(queue))+' availability holds in the current catalog.</p>'+'<div id="review-static">'+''.join(queue)+'</div><p id="review-count" role="status"></p><div id="review-list"></div><script src="review.js" defer></script>')
 (R/'docs/sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+B+p+'</loc><lastmod>2026-10-30</lastmod></url>' for p in paths)+'</urlset>')
 (R/'docs/robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+B+'sitemap.xml\n')
 return {'filters':filters,'packs':packs}
